import { execFileSync, spawnSync } from 'node:child_process';
import { randomBytes } from 'node:crypto';
import { chmodSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';

/**
 * F9 (T030, FR-013): the production Compose, with a PKI and passwords generated by this test, refuses
 * a connection without credentials and without TLS to PostgreSQL, Valkey and Temporal, refuses a
 * development password, and accepts the credentials of the test. The certificates and passwords
 * exist only in a temporary directory, created here and removed at the end; nothing is committed.
 * Requires Docker; runs inside the `integration` job on amd64 and arm64.
 */
const ROOT = resolve(import.meta.dirname, '../../..');
const COMPOSE = join(ROOT, 'deploy/compose.prod.yaml');
const PKI_SCRIPT = join(ROOT, 'deploy/provision/pki.sh');
const PROJECT = `cdag-sec-${randomBytes(3).toString('hex')}`;
/** The pinned admin-tools image of the compose, used as the Temporal client of the test. */
const UNUSED_IMAGE = 'registry.invalid/unused@sha256:' + '0'.repeat(64);

const work = mkdtempSync(join(tmpdir(), 'cdag-deploy-'));
const secrets = join(work, 'secrets');
const pki = join(work, 'pki');
const password = (): string => randomBytes(24).toString('base64url');
const pw = {
  superuser: password(),
  migrator: password(),
  runtime: password(),
  temporal: password(),
  valkey: password(),
};
const VALKEY_USER = 'cognitive_dag_app';

/** Forward slashes keep Docker Desktop on Windows happy; they are valid everywhere else. */
const posix = (path: string): string => path.replaceAll('\\', '/');

const env = (): NodeJS.ProcessEnv => ({
  ...process.env,
  COMPOSE_PROJECT_NAME: PROJECT,
  MSYS_NO_PATHCONV: '1',
  SECRETS_DIR: posix(secrets),
  PKI_DIR: posix(pki),
  // deploy.sh copies these directories to a stable path; the test mounts the repository's own.
  VALKEY_CONFIG_DIR: posix(join(ROOT, 'deploy/valkey')),
  POSTGRES_CONFIG_DIR: posix(join(ROOT, 'deploy/postgres')),
  TEMPORAL_CONFIG_DIR: posix(join(ROOT, 'deploy/temporal')),
  VALKEY_CONFIG_HASH: 'test',
  POSTGRES_CONFIG_HASH: 'test',
  TEMPORAL_CONFIG_HASH: 'test',
  SITE_DOMAIN: 'localhost',
  EDGE_IMAGE: UNUSED_IMAGE,
  API_IMAGE: UNUSED_IMAGE,
  WORKER_IMAGE: UNUSED_IMAGE,
  MIGRATOR_IMAGE: UNUSED_IMAGE,
  SMTP_HOST: 'smtp.invalid',
  MAIL_FROM: 'test <no-reply@localhost>',
});

function compose(args: string[], options: { allowFailure?: boolean } = {}) {
  const result = spawnSync('docker', ['compose', '-f', posix(COMPOSE), ...args], {
    env: env(),
    encoding: 'utf8',
    timeout: 240_000,
  });
  if (!options.allowFailure && result.status !== 0) {
    throw new Error(`docker compose ${args.join(' ')} failed:\n${result.stdout}\n${result.stderr}`);
  }
  return { status: result.status, output: `${result.stdout}${result.stderr}` };
}

/** Runs a command inside a running service; secrets travel as exec environment, never as arguments. */
function exec(service: string, command: string[], environment: Record<string, string> = {}) {
  const flags = Object.entries(environment).flatMap(([key, value]) => ['-e', `${key}=${value}`]);
  return compose(['exec', '-T', ...flags, service, ...command], { allowFailure: true });
}

const psql = (conninfo: string, secret: string) =>
  exec('postgres', ['psql', conninfo, '-tAc', 'select current_user'], { PGPASSWORD: secret });

const writeSecret = (name: string, value: string): void => {
  writeFileSync(join(secrets, name), value, { mode: 0o444 });
};

beforeAll(() => {
  mkdirSync(secrets, { recursive: true });
  execFileSync('bash', [posix(PKI_SCRIPT), 'init', posix(pki), '--key-mode', '0444'], {
    stdio: 'pipe',
  });
  writeSecret('postgres_superuser_password', pw.superuser);
  writeSecret('app_migrator_password', pw.migrator);
  writeSecret('app_runtime_password', pw.runtime);
  writeSecret('temporal_db_password', pw.temporal);
  writeSecret('valkey_password', pw.valkey);
  // The files are read by containers that run as other users: the test directory is private to it.
  chmodSync(work, 0o755);
  compose(['up', '-d', '--wait', 'postgres', 'valkey', 'temporal', 'temporal-init']);
}, 600_000);

afterAll(() => {
  compose(['down', '--volumes', '--remove-orphans'], { allowFailure: true });
  rmSync(work, { recursive: true, force: true });
}, 120_000);

describe('PostgreSQL of production', () => {
  const base = 'host=postgres port=5432 dbname=cognitive_dag';
  const trust = 'sslmode=verify-full sslrootcert=/run/secrets/ca.crt';

  it('refuses a connection without TLS, even with the right password', () => {
    const result = psql(`${base} user=app_runtime sslmode=disable`, pw.runtime);
    expect(result.status).not.toBe(0);
    expect(result.output).toMatch(/no pg_hba\.conf entry|encryption/i);
  });

  it('refuses a development password over TLS', () => {
    const result = psql(`${base} user=app_runtime ${trust}`, 'app_runtime_dev_only');
    expect(result.status).not.toBe(0);
    expect(result.output).toMatch(/password authentication failed/i);
  });

  it('refuses a connection without credentials', () => {
    const result = psql(`${base} user=app_runtime ${trust} connect_timeout=5`, '');
    expect(result.status).not.toBe(0);
  });

  it('accepts the credentials of the test over verified TLS', () => {
    const runtime = psql(`${base} user=app_runtime ${trust}`, pw.runtime);
    expect(runtime.output.trim()).toBe('app_runtime');
    const migrator = psql(`${base} user=app_migrator ${trust}`, pw.migrator);
    expect(migrator.output.trim()).toBe('app_migrator');
  });

  it('does not let the superuser in over the network', () => {
    const result = psql(`${base} user=postgres ${trust}`, pw.superuser);
    expect(result.status).not.toBe(0);
  });

  it('keeps app_runtime unable to bypass row-level security', () => {
    const result = psql(`${base} user=app_runtime ${trust}`, pw.runtime);
    const role = exec('postgres', [
      'psql',
      '-U',
      'postgres',
      '-tAc',
      "select rolbypassrls or rolsuper from pg_roles where rolname = 'app_runtime'",
    ]);
    expect(result.status).toBe(0);
    expect(role.output.trim()).toBe('f');
  });
});

describe('Valkey of production', () => {
  const cli = (args: string[], secret?: string) =>
    exec(
      'valkey',
      ['valkey-cli', '--tls', '--cacert', '/run/secrets/ca.crt', '--no-auth-warning', ...args],
      secret === undefined ? {} : { REDISCLI_AUTH: secret },
    );

  it('has no plain-text port', () => {
    const result = exec('valkey', ['valkey-cli', '-p', '6379', 'ping']);
    expect(result.output).not.toContain('PONG');
  });

  it('refuses a connection without credentials', () => {
    expect(cli(['ping']).output).toMatch(/NOAUTH|Authentication required/i);
  });

  it('refuses a development password', () => {
    const result = cli(['--user', VALKEY_USER, 'ping'], 'local_dev_only');
    expect(result.output).toMatch(/WRONGPASS|invalid/i);
    expect(result.output).not.toContain('PONG');
  });

  it('accepts the credentials of the test and refuses what the ACL does not list', () => {
    expect(cli(['--user', VALKEY_USER, 'ping'], pw.valkey).output).toContain('PONG');
    expect(cli(['--user', VALKEY_USER, 'flushall'], pw.valkey).output).toMatch(/NOPERM/);
    expect(cli(['--user', VALKEY_USER, 'config', 'get', 'maxmemory'], pw.valkey).output).toMatch(
      /NOPERM/,
    );
  });

  it('caps memory and never evicts', () => {
    const result = exec('valkey', ['sh', '-c', 'cat /etc/cdag/valkey/valkey.conf']);
    expect(result.output).toMatch(/^maxmemory 128mb$/m);
    expect(result.output).toMatch(/^maxmemory-policy noeviction$/m);
    expect(result.output).toMatch(/^port 0$/m);
  });
});

describe('Temporal of production', () => {
  const network = `${PROJECT}_backend`;
  const client = (args: string[], tls: boolean) => {
    const mounts = tls ? ['-v', `${posix(pki)}:/pki:ro`] : [];
    const flags = tls
      ? [
          '--tls',
          '--tls-ca-path=/pki/ca.crt',
          '--tls-cert-path=/pki/temporal-client-api.crt',
          '--tls-key-path=/pki/temporal-client-api.key',
          '--tls-server-name=temporal',
        ]
      : [];
    const user = typeof process.getuid === 'function' ? ['--user', String(process.getuid())] : [];
    const image = /image:\s*(temporalio\/admin-tools\S+)/.exec(readFileSync(COMPOSE, 'utf8'))?.[1];
    expect(image, 'the compose pins the admin-tools image').toBeDefined();
    const result = spawnSync(
      'docker',
      [
        'run',
        '--rm',
        '--network',
        network,
        ...user,
        ...mounts,
        image ?? '',
        'temporal',
        ...args,
        ...flags,
      ],
      { env: env(), encoding: 'utf8', timeout: 120_000 },
    );
    return { status: result.status, output: `${result.stdout}${result.stderr}` };
  };
  const health = ['operator', 'cluster', 'health', '--address', 'temporal:7233'];

  it('refuses a connection without TLS', () => {
    const result = client(health, false);
    expect(result.status).not.toBe(0);
  });

  it('refuses a TLS client that presents no certificate (mTLS)', () => {
    const user = typeof process.getuid === 'function' ? ['--user', String(process.getuid())] : [];
    const image = /image:\s*(temporalio\/admin-tools\S+)/.exec(readFileSync(COMPOSE, 'utf8'))?.[1];
    const result = spawnSync(
      'docker',
      [
        'run',
        '--rm',
        '--network',
        network,
        ...user,
        '-v',
        `${posix(pki)}:/pki:ro`,
        image ?? '',
        'temporal',
        ...health,
        '--tls',
        '--tls-ca-path=/pki/ca.crt',
        '--tls-server-name=temporal',
      ],
      { env: env(), encoding: 'utf8', timeout: 120_000 },
    );
    expect(result.status).not.toBe(0);
  });

  it('accepts the client certificate of the test', () => {
    const result = client(health, true);
    expect(result.output).toMatch(/SERVING/);
  });

  it('serves the namespace and the CorrelationId search attribute', () => {
    const namespaces = client(
      [
        'operator',
        'namespace',
        'describe',
        '--address',
        'temporal:7233',
        '--namespace',
        'cognitive-dag',
      ],
      true,
    );
    expect(namespaces.output).toMatch(/cognitive-dag/);
    const attributes = client(
      [
        'operator',
        'search-attribute',
        'list',
        '--address',
        'temporal:7233',
        '--namespace',
        'cognitive-dag',
      ],
      true,
    );
    expect(attributes.output).toMatch(/CorrelationId\s+Keyword/);
  });
});
